import {createSaveGuard} from './save-guard.js';
import {report} from './accounting.js';
import {Simulation} from './core.js';
import {ITEMS,BUILDINGS,RECIPES,ROLES,VEHICLES,RESEARCH} from './catalog.js';
import {Scene} from './scene.js';
import {onShift} from './workforce.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v=0,d=0)=>Number(v).toLocaleString('de-DE',{maximumFractionDigits:d});
const euro=v=>fmt(v,2)+' €';
const time=t=>`Tag ${Math.floor(t/1440)+1} · ${String(Math.floor(t%1440/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`;
const L={idle:'Bereit',working:'In Bearbeitung',walking:'Materialbereitstellung',materials:'Material fehlt',staff:'Personal fehlt',storage:'Ausgang blockiert',power:'Energie fehlt',broken:'Defekt',maintenance:'Wartung',paused:'Pausiert',offer:'Angebot',active:'Aktiv',fulfilled:'Erfüllt',cancelled:'Storniert',ordered:'Unterwegs',waiting:'Wartet',receiving:'Annahme',checking:'Prüfung',storing:'Einlagerung',stored:'Eingelagert',loading:'Beladung',transit:'Unterwegs',unloading:'Entladung',returning:'Rückfahrt',complete:'Abgeschlossen',tour:'Sammeltour',transfer:'Standorttransfer',stock:'Lager',inbound:'Wareneingang',machine:'Anlage',vehicle:'Fahrzeug',quarantine:'Quarantäne',company:'Eigenbestand',day:'Tagschicht · 08–16 Uhr',night:'Nachtschicht · 16–08 Uhr',all:'Durchgehend',standard:'Regulär',express:'Express',quality:'Premium'};
const label=x=>L[x]||x||'—';
const name=(cat,id)=>cat[id]?.name||id||'—';
Object.assign(L,{completed:'Abgeschlossen',setup:'Umrüsten',research:'Forschung fehlt',service:'Rücktransport',documents:'Dokumente fehlen',documentation:'Dokumentprüfung',processing:'Bearbeitung',handling:'Abfertigung',waiting_departure:'Wartet auf Anschluss',delivered:'Zugestellt',rail:'Bahn',sea:'Seefracht',air:'Luftfracht',collecting:'Abholung',inspection:'Retourenprüfung',decision:'Entscheidung offen',repair:'Reparatur',recycling:'Verwertung',repaired:'Repariert',recycled:'Verwertet',personal:'Personal',construction:'Anlagenbau',maintenance:'Wartung'});
let sim=new Simulation(), speed=1, panel='', selected=null, build=null, rotation=0, moving=null, search='', forecast=null, toastTimer, confirmAction=null;
let started=false, dirty=false, uiStamp=0, lastTick=performance.now(), accumulator=0;
const STORE='industrie-logistik-v1', prefsKey=STORE+'-prefs';
const guard=createSaveGuard({prefix:STORE,onLost(){writable=false;speed=0;$('#statusText').textContent=lockMessage();}});
let writable=false, switching=false;
const lockMessage=()=>guard.reason==='storage-error'?'Schreibschutz: Lokaler Speicher nicht verfügbar. Vorhandenen Stand als JSON exportieren.':guard.reason==='unsupported'?'Schreibschutz: Browser unterstützt keine sichere Tab-Sperre. JSON-Export bleibt möglich.':'Schreibschutz: Spielstand in anderem Tab geöffnet oder Sperre verloren. Anderen Tab schließen und hier neu laden.';
function canWrite(){if(writable&&guard.owns(sim.state.mode))return true;writable=false;speed=0;$('#statusText').textContent=lockMessage();return false;}
function resetView(){endBuild();closePanel();selected=null;forecast=null;search='';accumulator=0;scene.home();}
async function activate(mode,{candidate=null,reset=false}={}){
 if(switching)return false;switching=true;
 try{
  if(started&&writable&&!save())return false;
  if(!await guard.acquire(mode)){writable=false;speed=0;toast(lockMessage(),true);render();return false;}
  writable=true;
  const raw=localStorage.getItem(STORE+'-'+mode);
  const next=candidate||(reset?new Simulation({mode}):raw?Simulation.fromJSON(raw):new Simulation({mode}));
  sim=next;prefs.mode=sim.state.mode;started=true;dirty=!!candidate||reset||!raw;resetView();
  $('#welcome').close();setSpeed(0);render(true);
  if(dirty){if(!save())return false;}else localStorage.setItem(prefsKey,JSON.stringify(prefs));
  toast(reset?'Neues Unternehmen gegründet. Betrieb pausiert.':'Spielstand geladen. Betrieb pausiert.');return true;
 }catch(e){writable=false;speed=0;toast('Spielstandwechsel fehlgeschlagen: '+e.message,true);return false;}
 finally{switching=false;}
}
async function bootstrap(){
 try{writable=await guard.acquire(sim.state.mode);if(writable&&started){const raw=localStorage.getItem(STORE+'-'+sim.state.mode);if(raw)sim=Simulation.fromJSON(raw);}}
 catch(e){writable=false;toast('Speicher nicht verfügbar: '+e.message,true);}
 if(!writable){speed=0;$('#statusText').textContent=lockMessage();}render();if(!started)$('#welcome').showModal();
}

let prefs={mode:'guided',large:false,reduced:matchMedia('(prefers-reduced-motion: reduce)').matches,mission:true};
try{prefs={...prefs,...JSON.parse(localStorage.getItem(prefsKey)||'{}')};const saved=localStorage.getItem(STORE+'-'+prefs.mode);if(saved){sim=Simulation.fromJSON(saved);started=true;}}catch(e){setTimeout(()=>toast('Gespeicherter Stand nicht geladen: '+e.message,true),500);}
applyPrefs();
const scene=new Scene($('#world'),{onSelect(id){if(!id)return;if(sim.state.sites.some(x=>x.id===id)){send({type:'selectSite',id});scene.home();return;}selected=id;openPanel('detail');scene.focus?.(id);},onPlace(x,y){if(moving){const r=send({type:'move',id:moving,x,y,rotation});if(r.ok){moving=null;endBuild();}}else if(build)send({type:'build',buildingType:build,x,y,rotation,site:sim.state.selectedSite});},onHover(x,y){if(build)$('#buildHint').textContent=`${name(BUILDINGS,build)} · Raster ${x+1}/${y+1} · ${rotation}° · ${euro(BUILDINGS[build].cost)}`;}});
scene.setState(sim.state);
function toast(text,error=false){$('#toast').textContent=text;$('#toast').className='visible'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').className='',4500);}
function send(c,quiet=false){if(!canWrite()){toast(lockMessage(),true);return {ok:false,message:lockMessage()};}try{const r=sim.command(c);if(!r.ok)toast(r.message||'Aktion nicht möglich.',true);else{dirty=true;if(!quiet)toast(r.message||'Änderung übernommen.');}render(true);return r;}catch(e){toast(e.message,true);return {ok:false,message:e.message};}}
function save(show=false){if(!canWrite()){if(show)toast(lockMessage(),true);return false;}try{const key=STORE+'-'+sim.state.mode,old=localStorage.getItem(key);if(old){let valid=false;try{Simulation.fromJSON(old);valid=true;}catch{}if(valid)localStorage.setItem(key+'-backup',old);}localStorage.setItem(key,sim.serialize());localStorage.setItem(prefsKey,JSON.stringify({...prefs,mode:sim.state.mode}));dirty=false;$('#statusText').textContent='Gesichert · '+time(sim.state.t)+' · Keine Offlinefortschritte';if(show)toast('Spielstand gesichert.');return true;}catch(e){toast('Speichern fehlgeschlagen. Bitte Spielstand exportieren.',true);return false;}}
function applyPrefs(){document.body.classList.toggle('large',prefs.large);document.body.classList.toggle('reduced',prefs.reduced);document.body.classList.toggle('mission-hidden',!prefs.mission);}
function setSpeed(n){speed=n&&canWrite()?n:0;accumulator=0;lastTick=performance.now();$$('[data-speed]').forEach(b=>b.classList.toggle('active',+b.dataset.speed===speed));render();}
function openPanel(p){panel=p;search='';$('#search').value='';$('#panel').hidden=false;document.body.classList.add('panel-open');$('#panel').classList.toggle('wide',['inventory','finance','history','staff','network','planning'].includes(p));$$('.rail [data-panel]').forEach(b=>b.classList.toggle('active',b.dataset.panel===p));renderPanel();}
function closePanel(){panel='';$('#panel').hidden=true;document.body.classList.remove('panel-open');$$('.rail .active').forEach(b=>b.classList.remove('active'));}
function startBuild(type){closePanel();build=type||null;$('#buildTray').hidden=false;document.body.classList.add('build-open');scene.setBuild(build,rotation,moving);renderBuild();}
function endBuild(){build=null;moving=null;scene.setBuild(null);$('#buildTray').hidden=true;document.body.classList.remove('build-open');}
function renderBuild(){const icons={assembly:'⚒',testing:'⌁',packing:'▣',rack:'▤',dock:'⇥',power:'ϟ',workshop:'⚙',research:'⌘',coldstore:'❄',terminal:'⌂'};$('#buildItems').innerHTML=Object.entries(BUILDINGS).map(([id,b])=>`<button data-build="${id}" class="${id===build?'active':''}"><i>${icons[id]||'⊞'}</i><b>${esc(b.name)}</b><small>${euro(b.cost)} · ${b.w}×${b.h}</small></button>`).join('');}
function filtered(a){return a.filter(x=>!search||JSON.stringify(x).toLowerCase().includes(search)||Object.values(x).some(v=>String(name(ITEMS,v)).toLowerCase().includes(search)));}
const badge=(text,tone='')=>`<span class="badge ${tone}">${esc(text)}</span>`;
const empty=(title,text='')=>`<div class="empty"><strong>${esc(title)}</strong>${esc(text)}</div>`;
const kv=(k,v)=>`<div class="kv"><span>${esc(k)}</span><b>${v}</b></div>`;
const button=(text,action,id='',cls='')=>`<button class="${cls}" data-action="${action}" data-id="${esc(id)}">${text}</button>`;
const num=(v,t,neg=false)=>`<div class="number ${neg?'negative':''}"><b>${v}</b><small>${esc(t)}</small></div>`;
const opts=(cat,sel)=>Object.entries(cat).map(([id,v])=>`<option value="${id}" ${id===sel?'selected':''}>${esc(v.name||v)}</option>`).join('');
const field=(title,html,full=false)=>`<label class="field ${full?'full':''}">${esc(title)}${html}</label>`;
const progress=v=>`<div class="progress"><span style="width:${Math.max(0,Math.min(100,v*100))}%"></span></div>`;
function requirements(){const s=sim.state,b=s.buildings.filter(x=>x.site===s.selectedSite);return[
 {ok:['assembly','testing','packing'].every(t=>b.some(x=>x.type===t))&&b.some(x=>x.type==='rack'),title:'Produktionslinie errichten',text:'Montage, Prüfung, Packstation und Lagerregal.',action:'build',cta:'Anlagen bauen'},
 {ok:s.workers.filter(x=>x.role==='production').length>=3&&s.workers.some(x=>x.role==='warehouse')&&s.workers.some(x=>x.role==='driver'),title:'Team einstellen',text:'Drei Fertigungskräfte, eine Lagerkraft und ein Fahrer.',panel:'staff',cta:'Personal einstellen'},
 {ok:['housing','board','carton'].every(i=>s.purchases.some(p=>p.item===i)),title:'Material beschaffen',text:'Je 12 Gehäuse, LED-Platinen und Kartons bestellen.',panel:'purchasing',cta:'Material bestellen'},
 {ok:s.orders.some(o=>o.status!=='offer'),title:'Kundenauftrag annehmen',text:'Erster Kunde benötigt acht Arbeitsleuchten.',panel:'orders',cta:'Auftrag auswählen'},
 {ok:s.stats.produced>=8,title:'Leuchten fertigen',text:'Material wird angenommen, montiert, geprüft und verpackt.',panel:'production',cta:'Fertigung prüfen'},
 {ok:s.vehicles.length>0,title:'Lieferwagen anschaffen',text:'Eigene Flotte bringt deine Produkte zum Kunden.',panel:'fleet',cta:'Fahrzeug kaufen'},
 {ok:s.stats.delivered>=8,title:'Erste Lieferung zustellen',text:'Im Auftragsfenster Fahrzeug und echte Fertigware zuordnen.',panel:'orders',cta:'Lieferung planen'},
 {ok:s.orders.some(o=>o.paid>0),title:'Zahlung erhalten',text:'Nach Zustellung entsteht eine Forderung. Zahlung folgt später.',panel:'finance',cta:'Finanzen öffnen'}];}
function render(force=false){const s=sim.state;scene.setState(s);$('#cash').textContent=euro(s.money);$('#delivered').textContent=fmt(s.stats.delivered)+' Stück';$('#staffCount').textContent=fmt(s.workers.length);$('#clock').textContent=time(s.t);$('#siteName').textContent=s.sites.find(x=>x.id===s.selectedSite)?.name||'Standort';$('#worldTitle').textContent=s.buildings.length?'Dein Betrieb nimmt Fahrt auf.':'Aus Ideen wird Industrie.';$('#simState').textContent=!writable?'Schreibgeschützte Ansicht':document.hidden?'Hintergrundpause':speed?'Betrieb läuft':'Betrieb pausiert';const req=requirements(),i=req.findIndex(x=>!x.ok),m=req[i]||{title:'Erster Kreislauf geschlossen.',text:'Neue Aufträge, größere Kapazität, dein nächster Schritt.',panel:'overview',cta:'Betrieb weiterentwickeln'};$('#missionNumber').textContent=i<0?'✓':String(i+1).padStart(2,'0');$('#missionTitle').textContent=m.title;$('#missionText').textContent=m.text;const a=$('#missionAction');a.textContent=m.cta+' →';delete a.dataset.panel;delete a.dataset.action;if(m.panel)a.dataset.panel=m.panel;else a.dataset.action=m.action;
 if(panel&&(force||performance.now()-uiStamp>900)&&!document.activeElement?.matches('input,select,textarea'))renderPanel();}
const titles={overview:'Betriebszentrale',production:'Fertigung',inventory:'Lager & Materialfluss',purchasing:'Beschaffung',staff:'Dein Team',orders:'Markt & Aufträge',fleet:'Fuhrpark & Touren',finance:'Unternehmensrechnung',research:'Forschung & Produkte',rules:'Betriebsregeln',network:'Unternehmensnetz',service:'Kundendienst & Rückläufe',history:'Betriebschronik',help:'Betriebshandbuch',settings:'Spiel & Einstellungen',detail:'Objektakte',planning:'Planungsvorschau',special:'Speziallogistik'};
function renderPanel(){if(!panel)return;uiStamp=performance.now();const scroll=$('#panelBody').scrollTop;$('#panelTitle').textContent=titles[panel]||panel;$('#panelEyebrow').textContent=panel==='detail'?'ALLE DATEN. EIN ZUSAMMENHANG.':'INDUSTRIE & LOGISTIK';const renderers={overview:overview,production:production,inventory:inventory,purchasing:purchasing,staff:staff,orders:orders,fleet:fleet,finance:finance,research:research,rules:rules,network:network,service:service,history:history,help:help,settings:settings,detail:detail,planning:planning,special:special};$('#panelBody').innerHTML=(renderers[panel]||overview)();$('#panelBody').scrollTop=scroll;}
function overview(){const s=sim.state,req=requirements(),blocked=s.buildings.filter(b=>['materials','staff','power','storage','broken'].includes(b.status));return `<div class="numbers">${num(fmt(s.buildings.length),'Anlagen')}${num(fmt(s.orders.filter(o=>o.status==='active').length),'Aktive Aufträge')}${num(fmt(s.reputation)+' %','Reputation')}</div><section class="section"><div class="section-title"><h3>Vom leeren Werk zur ersten Lieferung</h3>${badge(req.filter(r=>r.ok).length+' / '+req.length)}</div><ol class="checklist">${req.map((r,i)=>`<li class="${r.ok?'done':''}"><span>${r.ok?'✓':i+1}</span><div><b>${r.title}</b><small>${r.text}</small></div></li>`).join('')}</ol></section>${s.buildings.length===0?`<div class="notice">Du bestimmst den Grundriss. Alternativ setzt der Aufbauassistent eine kompakte Linie durch reguläre Bau- und Einstellbefehle.</div>${button('Startbetrieb einrichten · ca. 32.000 €','starter','','primary')}`:''}<section class="section"><div class="section-title"><h3>Engpässe</h3>${badge(blocked.length+' Hinweise',blocked.length?'warn':'good')}</div>${blocked.map(b=>`<div class="list-row"><div><strong>${esc(name(BUILDINGS,b.type))}</strong><small>${label(b.status)} · ${esc(b.id)}</small></div>${button('Prüfen →','select',b.id)}</div>`).join('')||empty('Keine Anlagen blockiert','Warteursachen erscheinen hier.')}<div class="actions">${button('Planungsvorschau','panel-planning')}${button('Chronik','panel-history')}</div></section>`;}
function production(){const s=sim.state,rows=filtered(s.buildings.filter(b=>b.site===s.selectedSite));return `<div class="notice">Jede Station verarbeitet nur passende Rezepte. Material, Arbeitskraft, Energie und freie Ausgabe müssen verfügbar sein.</div>${rows.map(b=>{const j=s.jobs.find(j=>j.id===b.job);return `<div class="card"><div class="card-top"><div><h3>${esc(name(BUILDINGS,b.type))}</h3><small>${esc(b.id)} · Position ${b.x+1}/${b.y+1}</small></div>${badge(label(b.status),['materials','staff','storage','power','broken'].includes(b.status)?'warn':'')}</div>${j?progress(b.progress)+kv('Auftrag',esc(name(RECIPES,j.recipe)))+kv('Restzeit',fmt(j.remaining,1)+' Min.'):kv('Prozess',esc(name(RECIPES,b.recipe)))}${kv('Zustand',fmt(b.condition)+' %')}<div class="actions">${button('Details','select',b.id)}${button(b.enabled?'Pausieren':'Fortsetzen','toggle',b.id)}${button('Versetzen','move',b.id)}</div></div>`;}).join('')||empty('Noch keine Anlagen','Baue deine erste Linie über den Baumodus.')}<div class="actions">${button('Anlage bauen','build','','primary')}</div>`;}
function inventory(){const s=sim.state,batches=filtered(s.batches.filter(b=>b.qty>0&&b.site===s.selectedSite)),used=s.batches.filter(b=>b.qty>0&&b.site===s.selectedSite&&b.location!=='vehicle').reduce((n,b)=>n+b.qty,0),cap=40+s.buildings.filter(b=>b.site===s.selectedSite).reduce((n,b)=>n+(BUILDINGS[b.type]?.capacity||0),0);return `<div class="numbers">${num(fmt(used),'Einheiten am Standort')}${num(fmt(cap),'Lagerkapazität')}${num(fmt(s.reservations.reduce((n,r)=>n+r.qty,0)),'Reservierte Einheiten')}</div>${progress(used/cap)}<div class="table-wrap"><table><thead><tr><th>Charge / Artikel</th><th class="num">Menge</th><th>Ort</th><th>Eigentum</th><th class="num">Qualität</th><th></th></tr></thead><tbody>${batches.map(b=>`<tr><td><b>${esc(name(ITEMS,b.item))}</b><br><small class="muted">${esc(b.id)}</small></td><td class="num">${fmt(b.qty)}${b.reserved?`<br><small>${b.reserved} gebunden</small>`:''}</td><td>${esc(label(b.location))}</td><td>${esc(label(b.owner))}</td><td class="num">${fmt(b.quality)} %</td><td>${button('Akte','select',b.id)}</td></tr>`).join('')}</tbody></table></div>${!batches.length?empty('Lager leer','Bestelle Material. Eine Lagerkraft prüft und lagert jede Lieferung ein.'):''}<div class="actions">${button('Material einkaufen','panel-purchasing','','primary')}${button('Kapazität bauen','build')}</div>`;}
function purchasing(){const s=sim.state,materials=Object.fromEntries(Object.entries(ITEMS).filter(([id,v])=>['housing','board','carton','spare','metal','sensor_component'].includes(id)||v.purchasable));return `<section class="section"><h3>Material bestellen</h3><p class="fine" style="margin:9px 0 15px">Regulär: 30 Min. · Express: 10 Min. / +30 % · Premium: 45 Min. / +18 %, höhere Qualität.</p><form data-form="buy" class="form-grid">${field('Material',`<select name="item">${opts(materials)}</select>`,true)}${field('Menge','<input name="qty" type="number" min="1" max="1000" value="12" required>')}${field('Lieferant',`<select name="supplier"><option value="standard">Regulär</option><option value="express">Express</option><option value="quality">Premium</option></select>`)}<button class="primary">Verbindlich bestellen →</button></form><div class="actions">${button('Startmaterial · 12 Leuchten','buy-kit')}</div></section><section class="section"><div class="section-title"><h3>Bestellungen</h3>${badge(s.purchases.length+' Vorgänge')}</div>${filtered(s.purchases).slice().reverse().map(p=>`<div class="card"><div class="card-top"><h3>${p.qty} × ${esc(name(ITEMS,p.item))}</h3>${badge(label(p.status),p.blocked?'warn':p.status==='stored'?'good':'')}</div>${kv('Bestellwert',euro(p.cost))}${kv('Ankunft',time(p.eta))}${p.blocked?`<p>${esc(p.blocked)}</p>`:''}<small>${esc(p.id)} · ${label(p.supplier)}</small></div>`).join('')||empty('Keine offenen Bestellungen')}</section>`;}
function staff(){const s=sim.state;return `<form data-form="hire" class="form-grid"><label class="field">Rolle<select name="role">${opts(ROLES)}</select></label><button class="primary" style="grid-column:auto;align-self:end">Person einstellen</button></form><p class="fine" style="margin:10px 0 20px">Tagschicht 08–16 Uhr. Beschäftigte können nur eine Aufgabe gleichzeitig übernehmen. Lohn je aktiver Schichtminute.</p>${filtered(s.workers).map(w=>`<div class="card"><div class="card-top"><div><h3>${esc(w.name)}</h3><small>${esc(name(ROLES,w.role))} · ${euro(w.wage)}/h</small></div>${badge(onShift(w,s.t)?w.task?'Beschäftigt':'Bereit':'Feierabend')}</div><div class="grid2"><div>${kv('Qualifikation',fmt(w.skill,2)+'×')}${w.training?kv('Fortbildung',fmt(w.training.remaining)+' Min.'):''}${kv('Müdigkeit',fmt(w.fatigue)+' %')}</div><div>${kv('Tätigkeit',esc(w.activity||'Bereit'))}${kv('Standort',esc(s.sites.find(x=>x.id===w.site)?.name))}</div></div><select aria-label="Schicht für ${esc(w.name)}" data-shift="${w.id}">${['day','night','all'].map(k=>`<option value="${k}" ${k===w.shift?'selected':''}>${label(k)}</option>`).join('')}</select><div class="actions">${button('Schulen · 90 Min. / 900 €','train',w.id)}${button('Akte','select',w.id)}${s.sites.length>1?`<select aria-label="Person versetzen" data-relocate="${w.id}"><option value="">Standort wechseln …</option>${s.sites.filter(a=>a.id!==w.site).map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select>`:''}${button('Entlassen','fire',w.id,'danger')}</div></div>`).join('')||empty('Dein Team wartet auf dich','Für erste Linie: 3 Fertigung, 1 Lager, 1 Fahrdienst.')}`;}
function orders(){const s=sim.state;return `<div class="notice">Erst tatsächliche Zustellung erzeugt eine Forderung. Zahlung folgt 60 Spielminuten später. Verspätete Lieferungen erhalten 10 % Preisabschlag.</div>${filtered(s.orders).map(o=>`<div class="card"><div class="card-top"><div><h3>${esc(o.customer)}</h3><small>${esc(o.id)} · ${esc(name(ITEMS,o.item))} · ${o.kind==='logistics'?'Fremdlogistik':o.kind==='manufacturing'?'Auftragsfertigung':'Eigenprodukte'}</small></div>${badge(o.late?'Frist überschritten':label(o.status),o.late?'bad':o.status==='fulfilled'?'good':'')}</div><div class="numbers">${num(`${o.delivered} / ${o.qty}`,'Geliefert')}${num(euro(o.price),'Preis / Stück')}${num(fmt(o.quality)+' %','Mindestqualität')}</div>${kv('Lieferfrist',time(o.due))}${kv('Vertragswert',euro(o.qty*o.price))}${kv('Bezahlt',euro(o.paid))}${o.status==='offer'?`<div class="actions">${button('Auftrag annehmen','accept',o.id,'primary')}${button('Akte','select',o.id)}</div>`:o.status==='active'?`<form data-form="dispatch" data-id="${o.id}" class="form-grid">${field('Fahrzeug',`<select name="vehicleId" required>${s.vehicles.filter(v=>v.status==='idle'&&v.site===s.selectedSite).map(v=>`<option value="${v.id}">${esc(v.name)} · ${v.capacity} Plätze</option>`).join('')||'<option value="">Kein freies Fahrzeug</option>'}</select>`,true)}${field('Teilmenge',`<input name="qty" type="number" min="1" max="${o.qty-o.delivered}" value="${Math.min(o.qty-o.delivered,20)}" required>`)}<button class="primary" style="grid-column:auto;align-self:end">Lieferung starten →</button></form><div class="actions">${button('Akte','select',o.id)}${button('Stornieren','cancelOrder',o.id)}</div>`:button('Auftragsakte','select',o.id)}</div>`).join('')}`;}
function fleet(){const s=sim.state;return `<form class="form-grid" data-form="vehicle">${field('Fahrzeug',`<select name="vehicleType">${Object.entries(VEHICLES).map(([id,v])=>`<option value="${id}">${esc(v.name)} · ${euro(v.cost)}</option>`).join('')}</select>`,true)}<button class="primary">Fahrzeug anschaffen</button></form><section class="section" style="margin-top:22px"><h3>Deine Flotte</h3>${filtered(s.vehicles).map(v=>`<div class="card" style="margin-top:12px"><div class="card-top"><h3>${esc(v.name)}</h3>${badge(label(v.status))}</div>${kv('Ladeplätze',fmt(v.capacity))}${kv('Nutzlast',fmt(VEHICLES[v.type]?.weightCapacity||v.capacity*4)+' kg')}${kv('Zustand',fmt(v.condition)+' %')}<div class="actions">${button('Akte','select',v.id)}${button('Warten','vehicleMaintain',v.id)}</div></div>`).join('')||empty('Noch keine Fahrzeuge','Lieferwagen: 20 Ladeplätze, 9.000 €.')}</section><section class="section"><h3>Sendungen</h3>${filtered(s.shipments).slice().reverse().map(sh=>`<div class="card" style="margin-top:12px"><div class="card-top"><h3>${esc(sh.id)}</h3>${badge(label(sh.status),sh.blocked?'warn':'')}</div>${kv('Menge',fmt(sh.qty)+' Stück')}${kv('Nächster Schritt',fmt(sh.remaining)+' Min.')}${sh.blocked?`<p>${esc(sh.blocked)}</p>`:''}<div class="actions">${button('Verlauf','select',sh.id)}${sh.status==='loading'?button('Stornieren','cancelShipment',sh.id):''}</div></div>`).join('')||empty('Keine Sendungen','Plane eine Lieferung im Auftragsfenster.')}</section>${tourPanel(s)}`;}
function finance(){const s=sim.state,r=report(s),deliveries=deliveryRows(s),outstanding=deliveries.filter(sh=>sh.paymentAt&&!sh.paid).reduce((n,sh)=>n+(sh.invoiceAmount||0),0),goods=s.batches.filter(b=>b.owner==='company').reduce((n,b)=>n+b.qty*b.unitCost,0),payments=s.ledger.filter(l=>l.category==='Umsatz').reduce((n,l)=>n+l.amount,0);const categories={};for(const l of s.ledger)categories[l.category]=(categories[l.category]||0)+l.amount;return `<div class="numbers">${num(euro(s.money),'Kontostand')}${num(euro(r.receivables.total),'Offene Forderungen')}${num(euro(r.inventory.ownValue),'Warenmodellwert')}</div><div class="notice">Zahlungsübersicht: Investitionen und Einkauf sind Geldabflüsse. Daraus allein folgt kein operativer Gewinn. Material trägt Beschaffungskosten; fertige Produkte zusätzlich direkte Fertigungslöhne und Maschinenenergie.</div><section class="section"><h3>Geldfluss seit Unternehmensgründung</h3><div class="grid2">${[['Betrieb',r.cashflow.operating],['Investitionen',r.cashflow.investing],['Finanzierung',r.cashflow.financing],['Sonstige Buchungen',r.cashflow.other]].map(([k,v])=>`<div class="card">${kv(k,euro(v))}</div>`).join('')}</div>${kv('Geldbestand zu Beginn (aus Journal)',euro(r.cash.openingBalance))}${kv('Netto-Geldfluss',euro(r.cash.net))}</section><section class="section"><h3>Gebundenes Kapital und Verpflichtungen</h3>${kv('Eigene Waren · Modellwert',euro(r.inventory.ownValue))}${kv('Davon gesperrt',euro(r.inventory.blockedValue))}${kv('Laufende Fertigung · Materialanteil',euro(r.inventory.workInProgress))}${kv('Vorausbezahlte Beschaffung',euro(r.inventory.prepaidPurchases))}${kv('Fremde Waren · kein eigenes Vermögen',fmt(r.inventory.foreignQty)+' Stück')}${kv('Offene Forderungen',euro(r.receivables.total))}${kv('Davon überfällig',euro(r.receivables.overdue))}${kv('Kredit, Überziehung und Terminalgebühren',euro(r.liabilities.total))}<details><summary>Bewertungsregeln und Grenzen</summary>${r.limitations.map(x=>`<p>${esc(x)}</p>`).join('')}</details></section><section class="section"><h3>Offene Kundenrechnungen</h3>${r.receivables.rows.map(row=>`<div class="list-row"><div><strong>${esc(row.customer)}</strong><small>${esc(row.source)} · ${esc(row.id)} · fällig ${time(row.due)}</small></div><b>${euro(row.amount)}${row.overdue?' · überfällig':''}</b></div>`).join('')||empty('Keine offenen Forderungen')}</section><div class="grid2"><div class="card"><h3>Zahlungsströme nach Bereich</h3>${Object.entries(categories).map(([k,v])=>kv(label(k),`<span class="${v<0?'money-minus':'money-plus'}">${euro(v)}</span>`)).join('')}</div><div class="card"><h3>Vertrieb</h3>${kv('Bezahlter Kundenumsatz',euro(payments))}${kv('Ausgelieferte Einheiten',fmt(s.stats.delivered))}${kv('Reputation',fmt(s.reputation)+' %')}${kv('Aktive Verträge',fmt(s.orders.filter(o=>o.status==='active').length))}</div></div><section class="section"><h3>Lieferungsbeiträge</h3><p class="fine">Rechnungswert minus bewertete Herstellung und direkte Fracht. Standortmiete, Verwaltung und Finanzierung sind noch nicht verteilt.</p><div class="table-wrap" style="margin-top:10px"><table><thead><tr><th>Kunde / Route</th><th class="num">Rechnung</th><th class="num">Direkte Kosten</th><th class="num">Beitrag</th></tr></thead><tbody>${deliveries.filter(sh=>sh.deliveredAt).map(sh=>`<tr><td>${esc(s.orders.find(o=>o.id===sh.orderId)?.customer)}<br><small>${esc(sh.id)}</small></td><td class="num">${euro(sh.invoiceAmount||0)}</td><td class="num">${euro((sh.materialCost||0)+(sh.transportCost||0))}</td><td class="num">${euro((sh.invoiceAmount||0)-(sh.materialCost||0)-(sh.transportCost||0))}</td></tr>`).join('')}</tbody></table></div></section><section class="section"><h3>Finanzierung</h3>${kv('Darlehenssaldo · 8 % p.a.',euro(s.loanBalance||0))}${kv('Kontokorrent · 15 % p.a.',euro(s.overdraft||0))}<form data-form="loan" class="form-grid">${field('Betrag','<input name="amount" type="number" min="100" max="50000" value="10000" required>')}${field('Aktion','<select name="operation"><option value="takeLoan">Kredit aufnehmen</option><option value="repayLoan">Kredit tilgen</option></select>')}<button class="primary">Finanzierung ausführen</button></form><p class="fine">Pflichtkosten laufen bei Geldmangel ins Kontokorrent. Neue freiwillige Ausgaben benötigen ausreichende Liquidität.</p></section><section class="section"><div class="section-title"><h3>Buchungsjournal</h3>${badge(s.ledger.length+' Buchungen')}</div><div class="table-wrap"><table><thead><tr><th>Zeit</th><th>Bereich / Anlass</th><th class="num">Betrag</th></tr></thead><tbody>${filtered(s.ledger).slice(-120).reverse().map(l=>`<tr><td>${time(l.t)}</td><td>${esc(label(l.category))}<br><small class="muted">${esc(l.note)}</small></td><td class="num ${l.amount<0?'money-minus':'money-plus'}">${euro(l.amount)}</td></tr>`).join('')}</tbody></table></div><p class="fine">Letzte 120 Treffer. Gesamter Zustand bleibt im Export enthalten.</p></section>`;}
function research(){const s=sim.state;return `<div class="notice">Entwicklung verbindet Forschung, Personal und Anlagen. Laufende Projekte benötigen eine Entwicklungskraft und ein Labor.</div>${Object.entries(RESEARCH).map(([id,r])=>{const project=s.research.find(p=>p.key===id||p.type===id||p.id===id);return `<div class="card"><div class="card-top"><h3>${esc(r.name)}</h3>${badge(project?label(project.status):'Verfügbar')}</div>${kv('Investition',euro(r.cost))}${kv('Dauer',r.duration+' Min.')}${project?.blocked?`<p>${esc(project.blocked)}</p>`:''}${project?progress(1-(project.remaining||0)/r.duration):button('Forschung starten','research',id,'primary')}</div>`;}).join('')}<section class="section"><h3>Arbeitspläne</h3>${Object.entries(RECIPES).map(([id,r])=>`<div class="card" style="margin-top:10px"><h3>${esc(r.name)}</h3><p>${Object.entries(r.inputs).map(([i,q])=>q+' × '+esc(name(ITEMS,i))).join(' + ')} → ${r.output.qty} × ${esc(name(ITEMS,r.output.item))}</p>${kv('Nennzeit',r.duration+' Min.')}${kv('Anlage',esc(name(BUILDINGS,r.building)))}</div>`).join('')}</section>`;}
function rules(){const s=sim.state;return `<div class="notice">Betriebsregeln nutzen dieselben Material-, Personal- und Budgetgrenzen wie manuelle Eingaben. Kein zusätzlicher Ertrag durch Automatisierung.</div><form class="form-grid" data-form="rule">${field('Regelart','<select name="kind"><option value="reorder">Material nachbestellen</option><option value="dispatch">Kundenlieferungen disponieren</option><option value="maintenance">Anlagen warten</option></select>',true)}${field('Material (Nachbestellung)',`<select name="item">${opts(Object.fromEntries(Object.entries(ITEMS).filter(([id,v])=>v.purchasable)))}</select>`,true)}${field('Bestand- / Zustandsgrenze','<input name="threshold" type="number" min="1" value="5">')}${field('Menge je Bestellung / Fahrt','<input name="qty" type="number" min="1" value="20">')}${field('Gesamtbudget der Regel','<input name="budget" type="number" min="1" value="1000">')}${field('Wartezeit in Minuten','<input name="cooldown" type="number" min="10" value="120">')}${field('Priorität · höher zuerst','<input name="priority" type="number" min="0" max="100" value="50">')}<button class="primary">Betriebsregel anlegen</button></form><section class="section" style="margin-top:20px">${s.rules.map(r=>`<div class="card"><h3>${esc(r.name||(r.kind==='dispatch'?'Versandleitung':r.kind==='maintenance'?'Wartungsleitung':name(ITEMS,r.item)))}</h3>${kv('Zustand',r.enabled?'Aktiv':'Pausiert')}${kv('Budgetverbrauch',euro(r.spent||0)+' / '+euro(r.budget))}${kv('Letzte Ausführung',r.lastRun?time(r.lastRun):'Noch nicht')}${r.lastReason?`<p>${esc(r.lastReason)}</p>`:''}<div class="actions">${button(r.enabled?'Pausieren':'Aktivieren','toggleRule',r.id)}${button('Entfernen','deleteRule',r.id)}</div></div>`).join('')||empty('Keine Regeln','Starte mit einem Sicherheitsbestand für Kartons.')}</section>`;}
function network(){const s=sim.state;return `<div class="section-title"><h3>Standorte</h3>${button('Netzkarte','networkView')}</div><div class="grid2">${s.sites.map(a=>`<div class="card"><div class="card-top"><h3>${esc(a.name)}</h3>${badge(a.id===s.selectedSite?'Ausgewählt':'Standort')}</div>${kv('Fläche',a.width+' × '+a.height)}${kv('Anlagen',s.buildings.filter(b=>b.site===a.id).length)}${kv('Team',s.workers.filter(w=>w.site===a.id).length)}<div class="actions">${button('Standort öffnen','site',a.id,'primary')}</div></div>`).join('')}</div><form data-form="site" class="form-grid">${field('Neuer Standortname','<input name="name" value="Verteilzentrum Lindenhain" maxlength="60" required>',true)}<button class="primary">Standort erwerben · 25.000 €</button><small class="fine" style="grid-column:1/-1">Benötigt Forschung „Standortnetz“. Freies Bauen ohne Forschungssperre. Maximal acht Standorte.</small></form>${s.sites.length>1?`<section class="section" style="margin-top:20px"><h3>Ware zwischen Standorten transportieren</h3><form data-form="transfer" class="form-grid">${field('Artikel',`<select name="item">${opts(ITEMS)}</select>`)}${field('Menge','<input name="qty" type="number" min="1" value="10">')}${field('Ziel',`<select name="toSite">${s.sites.filter(a=>a.id!==s.selectedSite).map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select>`)}${field('Fahrzeug',`<select name="vehicleId">${s.vehicles.filter(v=>v.site===s.selectedSite&&v.status==='idle').map(v=>`<option value="${v.id}">${esc(v.name)}</option>`).join('')}</select>`)}<button class="primary">Transfer beauftragen</button></form></section>`:''}<section class="section" style="margin-top:20px"><h3>Standorttransfers</h3>${(s.transfers||[]).slice().reverse().map(t=>`<div class="card" style="margin-top:10px"><div class="card-top"><h3>${t.qty} × ${esc(name(ITEMS,t.item))}</h3>${badge(label(t.status),t.blocked?'warn':'')}</div>${kv('Von',esc(s.sites.find(a=>a.id===(t.fromSite||t.site))?.name))}${kv('Nach',esc(s.sites.find(a=>a.id===t.toSite)?.name))}${kv('Restzeit',fmt(t.remaining)+' Min.')}${t.blocked?`<p>${esc(t.blocked)}</p>`:''}</div>`).join('')||empty('Keine Transfers','Eigene Standorttransfers erzeugen keinen Umsatz.')}</section><div class="actions">${button('Planungsvorschau','panel-planning')}</div>`;}
function service(){const s=sim.state;return `<div class="notice">Rückläufe brauchen echte Ware, Abholung und Prüfung. Erstattung erfolgt einmalig. Gesperrte Ware bleibt unverkäuflich.</div><form data-form="return" class="form-grid">${field('Gelieferter Auftrag',`<select name="orderId">${s.orders.filter(o=>o.delivered>0).map(o=>`<option value="${o.id}">${esc(o.customer)} · ${o.delivered} geliefert</option>`).join('')||'<option value="">Noch keine Zustellung</option>'}</select>`,true)}${field('Rückgabemenge','<input name="qty" type="number" min="1" value="1">')}<button class="primary" style="grid-column:auto;align-self:end">Rücknahme beauftragen</button></form><section class="section" style="margin-top:20px">${s.returns.map(r=>`<div class="card"><div class="card-top"><h3>${esc(r.id)}</h3>${badge(label(r.status))}</div>${kv('Menge',fmt(r.qty))}${r.blocked?`<p>${esc(r.blocked)}</p>`:''}<div class="actions">${button('Reparieren','repairReturn',r.id)}${button('Verwerten','recycleReturn',r.id)}</div></div>`).join('')||empty('Keine Rückläufe','Zustellungen bilden die Grundlage späterer Rücknahmen.')}</section>`;}
function history(ref=null){const rows=filtered(sim.state.events.filter(e=>!ref||e.refs?.includes(ref))).slice(-150).reverse();return `<div class="timeline">${rows.map(e=>`<div class="timeline-item"><small>${time(e.t)} · ${esc(e.kind)}</small><p>${esc(e.text)}</p>${e.refs?.length?`<div class="actions">${e.refs.slice(0,3).map(id=>button(esc(id),'select',id)).join('')}</div>`:''}</div>`).join('')||empty('Noch keine Ereignisse')}</div>`;}
function detail(){const s=sim.state;let kind='',o;for(const k of ['buildings','workers','batches','orders','purchases','vehicles','shipments','returns','transfers','tours','freights']){o=(s[k]||[]).find(x=>x.id===selected);if(o){kind=k;break;}}if(!o)return empty('Objekt nicht gefunden','Einige abgeschlossene Arbeitsaufträge gehen in die Chronik über.');let html=`<div class="card"><div class="card-top"><h3>${esc(o.name||o.customer||name(kind==='buildings'?BUILDINGS:ITEMS,o.type||o.item)||o.id)}</h3>${badge(o.id)}</div>`;if(kind==='buildings'){const d=BUILDINGS[o.type];html+=kv('Status',label(o.status))+kv('Zustand',fmt(o.condition)+' %')+kv('Energiebedarf',d.power+' kW')+kv('Anschaffung',euro(d.cost));if(d.recipes.length)html+=`<label class="field">Arbeitsplan<select data-recipe="${o.id}">${d.recipes.map(id=>`<option value="${id}" ${id===o.recipe?'selected':''}>${esc(name(RECIPES,id))}</option>`).join('')}</select></label>`;html+=`<div class="actions">${button(o.enabled?'Pausieren':'Fortsetzen','toggle',o.id)}${button('Warten','maintain',o.id)}${button('Versetzen','move',o.id)}${button('Abreißen · 35 % Erlös','demolish',o.id,'danger')}</div>`;}else if(kind==='batches'){html+=kv('Artikel',esc(name(ITEMS,o.item)))+kv('Menge',fmt(o.qty))+kv('Reserviert',fmt(o.reserved))+kv('Ort',label(o.location))+kv('Eigentum',esc(label(o.owner)))+kv('Qualität',fmt(o.quality)+' %')+kv('Einstandspreis',euro(o.unitCost));html+=`<div class="actions">${button('Charge und Nachfolger sperren','recallBatch',o.id,'danger')}</div><p>Herkunft: ${(o.parents||[]).map(id=>button(esc(id),'select',id)).join(' ')||'Direkte Anlieferung'}</p>`;}else{for(const [k,title]of Object.entries({status:'Status',role:'Rolle',item:'Artikel',qty:'Menge',delivered:'Geliefert',remaining:'Restzeit',quality:'Qualität',condition:'Zustand',blocked:'Warteursache',task:'Tätigkeit',capacity:'Ladeplätze',paid:'Bezahlt'}))if(o[k]!==undefined)html+=kv(title,esc(k==='item'?name(ITEMS,o[k]):k==='role'?name(ROLES,o[k]):label(o[k])));}return html+'</div><h3 style="margin:20px 0">Verlauf</h3>'+history(o.id);}
function planning(){const s=sim.state;return `<div class="notice good">Planung läuft auf vollständiger Kopie. Originalbestand, Geld und Zufallszustand bleiben unverändert. Prognose setzt heutige Befehle fort; neue Marktentscheidungen werden nicht erfunden.</div><form data-form="forecast" class="form-grid">${field('Zeitraum','<select name="minutes"><option value="60">1 Spielstunde</option><option value="480">8 Spielstunden</option><option value="1440">1 Spieltag</option></select>')}${field('Alternative','<select name="alternative"><option value="none">Aktuellen Betrieb fortführen</option><option value="worker">Zusätzliche Fertigungskraft</option></select>')}<button class="primary">Vorschau berechnen</button></form>${forecast?`<div class="forecast-comparison" style="margin-top:20px"><div class="card"><h3>Jetzt</h3>${kv('Geld',euro(s.money))}${kv('Fertigware erzeugt',s.stats.produced)}${kv('Ausgeliefert',s.stats.delivered)}</div><div class="card"><h3>${time(forecast.t)}</h3>${kv('Geld',euro(forecast.money))}${kv('Fertigware erzeugt',forecast.stats.produced)}${kv('Ausgeliefert',forecast.stats.delivered)}</div></div>`:''}`;}
function help(){return `<div class="notice good">Alle Firmen, Personen, Preise und Verkehrsregeln sind fiktive Spielwerte. Simulation bleibt lokal. Keine Offlinefortschritte.</div>${[
 ['Erste Lieferung','Errichte Lagerregal, Montageplatz, Prüfstation, Packstation und Laderampe. Stelle drei Fertigungskräfte, eine Lagerkraft und eine Fahrperson ein. Kaufe je zwölf Gehäuse, Platinen und Kartons. Nimm ersten Auftrag an. Kaufe Lieferwagen. Sobald acht verpackte Leuchten vorliegen, Lieferung im Auftragsfenster starten.'],
 ['Material und Maschinen','Gehäuse + Platine → montierte Leuchte. Prüfstation → geprüfte Leuchte. Packstation + Karton → verkaufbare Leuchte. Anlagen wählen automatisch ihren ersten Arbeitsplan. Jedes Stück benötigt Arbeitszeit, Personal und Strom.'],
 ['Warum wartet mein Betrieb?','Material fehlt: Einkauf und Wareneingang prüfen. Personal fehlt: Rolle, Schicht und andere Tätigkeiten prüfen. Ausgang blockiert: Lager erweitern oder Ware ausliefern. Energie fehlt: Versorgung ausbauen. Gebäude anklicken für Details.'],
 ['Schichten und Zeit','Tagschicht: 08 bis 16 Uhr. Nachtschicht: 16 bis 08 Uhr. Durchgehend ist eine vereinfachte Spieloption mit Müdigkeit. Zeitraffer steuert nur Spielgeschwindigkeit. Hintergrund und geschlossene Seite erzeugen keinen Fortschritt.'],
 ['Bauen und Wege','Baumodus mit B öffnen. Anlage wählen und Rasterfläche anklicken. R dreht gewählte Anlage. Wege vom Wareneingang müssen zu allen Anlagen offen bleiben. Laufende Arbeitsvorgänge verhindern Abriss. Leere Anlage kann über ihre Akte versetzt werden.'],
 ['Lager, Ladung und Zahlung','Reservierte Ware ist für andere Aufträge gesperrt. Eine Lieferung darf vorhandene Ware und Ladeplätze nicht überschreiten. Nach Zustellung entsteht Forderung; Zahlung kommt später. Jeder Geldeingang besitzt genau einen Buchungsschlüssel.'],
 ['Speichern und Sicherung','Automatische Sicherung alle 20 Sekunden sowie beim Verlassen. Derselbe Modus besitzt nur einen schreibenden Tab; weitere Tabs bleiben pausiert. Modus laden in Einstellungen erhält vorhandene Unternehmen. Nach Laden oder Neugründung startet Betrieb pausiert: 1× drücken. Jeder Spielmodus besitzt eigenen Speicherplatz und letzte Sicherung. Exportiere JSON regelmäßig für geräteunabhängige Aufbewahrung. Import wird vor Übernahme geprüft.'],
 ['Steuerung und Zugänglichkeit','Leertaste: Pause. B: Bauen. R: Bauobjekt drehen. Escape: Fenster schließen. Ziehen: Kamera bewegen. Mausrad: Zoom. Grundriss liefert ebene Ersatzansicht. Alle Anlagen auch über Fertigungstabelle auswählen. Schrift und Bewegung in Einstellungen.'],
 ['Darstellung und Umfang','Die aktuelle räumliche Ansicht verwendet lokal gezeichnete Canvas-Isometrie. Sie benötigt kein WebGL. Phasenstatus und konkrete Grenzen sind in der ausgelieferten Dokumentation nachgehalten.']
 ].map(([h,t])=>`<details><summary>${h}</summary><p>${t}</p></details>`).join('')}`;}
function settings(){return `<section class="section"><h3>Spielstand</h3>${!writable?`<div class="notice">${esc(lockMessage())}</div>`:''}<form data-form="loadMode" class="form-grid">${field('Gespeichertes Unternehmen','<select name="mode"><option value="guided">Geführter Einstieg</option><option value="economy">Wirtschaftsbetrieb</option><option value="sandbox">Freies Bauen</option></select>')}<button>Modus laden</button></form><p class="fine">Entwicklungsfassung 0.5. Vollständiger Funktionsstatus und Quellcode im Download.</p><p style="margin:10px 0"><a href="./Industrie-Logistik.zip" download>Spielpaket & Quellcode herunterladen ↗</a></p><p class="fine" style="margin-top:8px">Aktiver Modus: ${sim.state.mode==='guided'?'Geführter Einstieg':sim.state.mode==='sandbox'?'Freies Bauen':'Wirtschaftsbetrieb'}</p><div class="actions">${button('Jetzt speichern','save','','primary')}${button('JSON exportieren','export')}${button('JSON importieren','import')}${button('Letzte Sicherung laden','backup')}</div></section><section class="section"><h3>Darstellung</h3><div class="list-row"><span>Größere Schrift</span><input type="checkbox" data-pref="large" ${prefs.large?'checked':''} aria-label="Größere Schrift"></div><div class="list-row"><span>Bewegung reduzieren</span><input type="checkbox" data-pref="reduced" ${prefs.reduced?'checked':''} aria-label="Bewegung reduzieren"></div><div class="list-row"><span>Einstiegshinweise</span><input type="checkbox" data-pref="mission" ${prefs.mission?'checked':''} aria-label="Einstiegshinweise"></div></section><section class="section"><h3>Unternehmen</h3><div class="actions">${button('Neues Unternehmen','new','','danger')}${button('Handbuch','panel-help')}</div><p class="fine" style="margin-top:10px">Neustart erfolgt erst nach Bestätigung. Vorheriger Stand kann exportiert werden.</p></section><div class="notice">Browserprüfung dieser Veröffentlichung noch offen. Fachliche Simulation wird automatisiert geprüft.</div>`;}
function confirm(title,text,action){$('#confirmTitle').textContent=title;$('#confirmText').textContent=text;confirmAction=action;$('#confirm').showModal();}
function starter(){const plans=[['rack',2,2],['assembly',5,3],['testing',9,3],['packing',13,3],['dock',3,11]];for(const [buildingType,x,y]of plans)if(!sim.state.buildings.some(b=>b.type===buildingType)){if(!send({type:'build',buildingType,x,y,rotation:0},true).ok)return;}for(const role of ['production','production','production','warehouse','driver'])if(!send({type:'hire',role},true).ok)return;if(!sim.state.vehicles.length)send({type:'buyVehicle',vehicleType:'van'},true);toast('Startbetrieb eingerichtet. Nächster Schritt: Material bestellen.');openPanel('purchasing');}
document.addEventListener('click',e=>{const b=e.target.closest('button,a.brand');if(!b)return;if(b.matches('a.brand')){e.preventDefault();openPanel('overview');return;}if(b.dataset.panel){openPanel(b.dataset.panel);return;}if(b.dataset.speed!==undefined){setSpeed(+b.dataset.speed);return;}if(b.dataset.view){scene.setView(b.dataset.view);$$('[data-view]').forEach(x=>x.classList.toggle('active',x===b));return;}if(b.dataset.camera){({plus:()=>scene.zoom(1),minus:()=>scene.zoom(-1),rotate:()=>scene.rotate(),home:()=>scene.home()})[b.dataset.camera]();return;}if(b.dataset.build){build=b.dataset.build;scene.setBuild(build,rotation,moving);renderBuild();return;}const a=b.dataset.action,id=b.dataset.id;if(!a)return;if(a.startsWith('panel-')){openPanel(a.slice(6));return;}
 const actions={disposeBatch:()=>confirm('Geschädigte Ware entsorgen?','Entsorgung kostet 2 € je Stück. Ware wird endgültig entfernt.',()=>send({type:'disposeBatch',batchId:id})),approveDocuments:()=>send({type:'approveDocuments',id}),cancelFreight:()=>confirm('Fracht stornieren?','Bereits gezahlte Fracht verfällt. Ware kehrt nur bei freier Lagerkapazität zurück.',()=>send({type:'cancelFreight',id})),recallBatch:()=>confirm('Charge zurückrufen?','Betroffene Charge und ihre nachverfolgbaren Nachfolger werden gesperrt. Bereits gelieferte Ware wird im Rückruf erfasst.',()=>send({type:'recallBatch',batchId:id})),close:closePanel,refresh:renderPanel,build:()=>startBuild(),endBuild,rotateBuild:()=>{rotation=(rotation+90)%360;scene.setBuild(build,rotation,moving);toast('Anlage gedreht: '+rotation+'°');},select:()=>{selected=id;openPanel('detail');scene.focus?.(id);},toggle:()=>send({type:'toggleBuilding',id}),maintain:()=>send({type:'maintain',id}),move:()=>{const o=sim.state.buildings.find(b=>b.id===id);if(o){moving=id;rotation=o.rotation;startBuild(o.type);toast('Neue Position auf Karte wählen.');}},demolish:()=>confirm('Anlage zurückbauen?','Rückbau gibt 35 % Anschaffungskosten zurück. Belegte Anlagen bleiben geschützt.',()=>send({type:'demolish',id})),accept:()=>send({type:'acceptOrder',id}),cancelOrder:()=>confirm('Auftrag stornieren?','Unvollständige Aufträge senken Reputation.',()=>send({type:'cancelOrder',id})),cancelShipment:()=>send({type:'cancelShipment',id}),train:()=>send({type:'train',id}),fire:()=>confirm('Person entlassen?','Aktive Tätigkeit muss vorher abgeschlossen werden.',()=>send({type:'fire',id})),vehicleMaintain:()=>send({type:'maintainVehicle',id}),research:()=>send({type:'startResearch',key:id}),toggleRule:()=>send({type:'toggleRule',id}),deleteRule:()=>send({type:'deleteRule',id}),site:()=>{send({type:'selectSite',id});scene.home();closePanel();},networkView:()=>{scene.setView('network');closePanel();},repairReturn:()=>send({type:'resolveReturn',id,resolution:'repair'}),recycleReturn:()=>send({type:'resolveReturn',id,resolution:'recycle'}),starter, 'buy-kit':()=>{for(const item of ['housing','board','carton'])if(!send({type:'buy',item,qty:12,supplier:'standard'},true).ok)return;toast('Drei getrennte Materiallieferungen bestellt.');},save:()=>save(true),export:()=>{const blob=new Blob([sim.serialize()],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`Industrie-Logistik-Tag-${Math.floor(sim.state.t/1440)+1}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);},import:()=>$('#importFile').click(),backup:()=>confirm('Letzte Sicherung laden?','Aktueller Fortschritt wird durch letzte Sicherung ersetzt.',()=>{try{const text=localStorage.getItem(STORE+'-'+sim.state.mode+'-backup');const restored=Simulation.fromJSON(text);return activate(restored.state.mode,{candidate:restored});}catch(e){toast(e.message,true);}}),new:()=>confirm('Neues Unternehmen?','Vorherigen Spielstand bei Bedarf zuerst exportieren. Moduswahl öffnet sich danach.',()=>{$('#welcome').showModal();setSpeed(0);}),hideMission:()=>{prefs.mission=false;applyPrefs();},start:()=>{const mode=$('input[name=mode]:checked').value;if(localStorage.getItem(STORE+'-'+mode)){confirm('Vorhandenen Spielstand ersetzen?','Dieser Modus besitzt bereits ein Unternehmen. Vorher bei Bedarf laden und exportieren. Letzte Sicherung bleibt erhalten.',()=>activate(mode,{reset:true}));return;}return activate(mode,{reset:true});},confirmCancel:()=>$('#confirm').close(),confirmOk:()=>{$('#confirm').close();const fn=confirmAction;confirmAction=null;return fn?.();}};return actions[a]?.();});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.relocate&&t.value)send({type:'moveWorker',id:t.dataset.relocate,toSite:t.value});if(t.dataset.shift)send({type:'setShift',id:t.dataset.shift,shift:t.value});if(t.dataset.recipe)send({type:'setRecipe',id:t.dataset.recipe,recipe:t.value});if(t.dataset.pref){prefs[t.dataset.pref]=t.checked;applyPrefs();try{localStorage.setItem(prefsKey,JSON.stringify({...prefs,mode:sim.state.mode}));}catch{}}});
$('#search').addEventListener('input',e=>{search=e.target.value.toLowerCase();renderPanel();});
document.addEventListener('submit',e=>{const f=e.target.closest('[data-form]');if(!f)return;e.preventDefault();const d=Object.fromEntries(new FormData(f));const t=f.dataset.form;for(const k of ['qty','threshold','budget','cooldown','minutes','amount','qty1','qty2','qty3','priority'])if(k in d)d[k]=Number(d[k]);const commands={freight:{type:'bookFreight',...d},tour:{type:'dispatchTour',vehicleId:d.vehicleId,stops:[1,2,3].filter(i=>d['order'+i]).map(i=>({orderId:d['order'+i],qty:d['qty'+i]}))},loan:{type:d.operation,amount:d.amount},buy:{type:'buy',...d},hire:{type:'hire',...d},vehicle:{type:'buyVehicle',...d},dispatch:{type:'dispatch',orderId:f.dataset.id,...d},rule:{type:'addRule',kind:'reorder',...d},site:{type:'buySite',...d},transfer:{type:'transfer',...d},return:{type:'createReturn',...d}};if(t==='loadMode'){return activate(d.mode);}if(t==='forecast'){try{forecast=sim.forecast(d.minutes,d.alternative==='worker'?[{type:'hire',role:'production'}]:[]);renderPanel();toast('Vorschau berechnet. Echter Betrieb unverändert.');}catch(err){toast(err.message,true);}}else{send(commands[t]);renderPanel();}});
$('#importFile').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>30000000)throw Error('Datei zu groß.');const candidate=Simulation.fromJSON(await file.text());confirm('Spielstand importieren?',`${time(candidate.state.t)} · ${euro(candidate.state.money)} · ${candidate.state.buildings.length} Anlagen. Aktuellen Stand ersetzen?`,()=>activate(candidate.state.mode,{candidate}));}catch(err){toast(err.message,true);}});
document.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea')||$('dialog[open]'))return;if(e.code==='Space'){e.preventDefault();setSpeed(speed?0:1);}if(e.key.toLowerCase()==='b')startBuild();if(e.key.toLowerCase()==='r'&&!$('#buildTray').hidden){rotation=(rotation+90)%360;scene.setBuild(build,rotation,moving);}if(e.key==='Escape'){endBuild();closePanel();}});
document.addEventListener('visibilitychange',()=>{accumulator=0;lastTick=performance.now();if(document.hidden&&started)save();render();});
window.addEventListener('beforeunload',()=>{if(started&&dirty)save();});
window.addEventListener('pagehide',()=>guard.release());
window.addEventListener('pageshow',e=>{if(e.persisted){writable=false;speed=0;toast('Ansicht wiederhergestellt. Für sicheres Fortsetzen Seite neu laden.',true);render();}});
setInterval(()=>{const now=performance.now(),dt=Math.min(1000,now-lastTick);lastTick=now;if(!started||switching||document.hidden||$('dialog[open]')||!speed||!canWrite()){accumulator=0;return;}accumulator+=dt*speed;const n=Math.floor(accumulator/1000);if(n){accumulator-=n*1000;try{sim.step(n);dirty=true;render();}catch(e){setSpeed(0);toast('Simulation angehalten: '+e.message,true);}}},100);
setInterval(()=>{if(started&&dirty)save();},20000);
const ready=bootstrap();

/** Sammeltouren nutzen dieselben Auftrags-IDs und Fahrzeuge wie Einzellieferungen. */
function tourPanel(s){const active=s.orders.filter(o=>o.status==='active');return `<section class="section"><h3>Sammeltour planen</h3><p class="fine" style="margin:8px 0 14px">Mehrere Kunden, eine Beladung. Gesamtgewicht und Volumen müssen ins Fahrzeug passen. Rückfahrt nach letztem Stopp.</p><form data-form="tour" class="form-grid">${field('Fahrzeug',`<select name="vehicleId">${s.vehicles.filter(v=>v.site===s.selectedSite&&v.status==='idle').map(v=>`<option value="${v.id}">${esc(v.name)} · ${v.capacity} Plätze</option>`).join('')||'<option value="">Kein freies Fahrzeug</option>'}</select>`,true)}${[1,2,3].map(i=>field('Stopp '+i,`<select name="order${i}"><option value="">${i===1?'Kunde auswählen':'Optionaler Stopp'}</option>${active.map(o=>`<option value="${o.id}">${esc(o.customer)} · ${o.qty-o.delivered} offen</option>`).join('')}</select>`)+field('Menge',`<input name="qty${i}" type="number" value="2" min="1" max="1000">`)).join('')}<button class="primary">Sammeltour verbindlich planen</button></form>${(s.tours||[]).slice().reverse().map(t=>`<div class="card" style="margin-top:15px"><div class="card-top"><h3>${esc(t.id)}</h3>${badge(label(t.status),t.blocked?'warn':'')}</div>${kv('Stopps',String(t.stops?.length||0))}${kv('Restzeit',fmt(t.remaining)+' Min.')}${t.blocked?`<p>${esc(t.blocked)}</p>`:''}${(t.stops||[]).map(st=>kv(s.orders.find(o=>o.id===st.orderId)?.customer||st.orderId,st.qty+' Stück · '+(st.status==='delivered'?'zugestellt':'geplant'))).join('')}</div>`).join('')}</section>`;}

function special(){const s=sim.state,cold=s.batches.filter(b=>b.qty>0&&ITEMS[b.item]?.cold);return `<div class="notice">Kalibriermodule benötigen passende Kühlung. Temperatur wirkt über Zeit auf Qualität. Frachtklassen und Dokumente folgen fiktiven Spielregeln.</div><section class="section"><h3>Kühlkette</h3>${cold.map(b=>`<div class="card" style="margin-top:10px"><div class="card-top"><h3>${b.qty} × ${esc(name(ITEMS,b.item))}</h3>${badge(b.blocked?'Gesperrt':label(b.location),b.blocked?'bad':'')}</div>${kv('Temperatur',fmt(b.temperature??20,1)+' °C')}${kv('Qualität',fmt(b.quality,1)+' %')}${kv('Wärmeexposition',fmt(b.exposure||0)+' Min.')}${button('Chargenakte','select',b.id)}${b.coldDamaged&&b.owner==='company'?button('Entsorgen · 2 €/Stk.','disposeBatch',b.id,'danger'):''}</div>`).join('')||empty('Keine temperaturgeführte Ware','Forschung Kühlkettenlogistik, Kühllager und Kühlfahrzeug vorbereiten.')}</section><section class="section"><h3>Bahn, See und Luft</h3><p class="fine" style="margin:8px 0 15px">Buchbare Fremdleistungen ab eigenem Terminal. Dokumentprüfung, Umschlag und Fahrplan bestimmen tatsächliche Abfahrt.</p><form data-form="freight" class="form-grid">${field('Aktiver Auftrag',`<select name="orderId">${s.orders.filter(o=>o.status==='active').map(o=>`<option value="${o.id}">${esc(o.customer)} · ${esc(name(ITEMS,o.item))}</option>`).join('')||'<option value="">Kein aktiver Auftrag</option>'}</select>`,true)}${field('Verkehrsträger','<select name="mode"><option value="rail">Bahn</option><option value="sea">Seefracht</option><option value="air">Luftfracht</option></select>')}${field('Menge','<input name="qty" type="number" min="1" max="1000" value="8">')}<button class="primary">Fracht verbindlich buchen</button></form></section><section class="section"><h3>Frachtaufträge</h3>${(s.freights||[]).slice().reverse().map(f=>`<div class="card" style="margin-top:10px"><div class="card-top"><h3>${esc(label(f.mode))} · ${f.qty} Stück</h3>${badge(label(f.status),f.blocked?'warn':'')}</div>${kv('Auftrag',esc(s.orders.find(o=>o.id===f.orderId)?.customer||f.orderId))}${kv(f.departedAt?'Abgefahren':'Nächster Fahrplan',time(f.departedAt||f.nextDeparture))}${kv('Dokumente',f.documents==='approved'?'Freigegeben':f.documents==='processing'?'Prüfung · '+f.documentRemaining+' Min.':'Prüfung erforderlich')}${kv('Verpasste Anschlüsse',fmt(f.missedConnections||0))}${kv('Restzeit',fmt(f.remaining)+' Min.')}${f.blocked?`<p>${esc(f.blocked)}</p>`:''}<div class="actions">${f.documents==='pending'&&f.status!=='cancelled'?button('Dokumentprüfung starten','approveDocuments',f.id):''}${button('Akte','select',f.id)}${['loading','waiting'].includes(f.status)?button('Stornieren · Fracht verfällt','cancelFreight',f.id):''}</div></div>`).join('')||empty('Keine gebuchten Frachten')}</section>`;}

/** Einheitliche Auswertung aller tatsächlichen Zustellungen, ohne neue Geldbuchung. */
function deliveryRows(s){return [...s.shipments,...(s.freights||[]).map(f=>({...f,transportCost:f.tripCost??f.transportCost})),...(s.tours||[]).flatMap(t=>t.stops.map((st,i)=>({...st,id:t.id+' / '+(i+1),transportCost:(t.transportCost||0)*st.qty/t.stops.reduce((n,x)=>n+x.qty,0)})))];}
